function t(k){return texts[lang][k]||k}function el(tag,attrs,parent=svg){const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));parent.appendChild(n);return n}
el('rect',{x:0,y:0,width:P.WIDTH,height:P.HEIGHT,fill:'#eff5f1'});el('path',{d:'M 0 31 C 10 26, 18 33, 29 28 S 49 14, 60 19 L 60 22 C 50 17, 40 27, 30 31 S 9 30, 0 34 Z',class:'river'});for(let i=4;i<P.WIDTH;i+=8)el('path',{d:`M ${i} 0 L ${i} ${P.HEIGHT}`,class:'road'});for(let i=4;i<P.HEIGHT;i+=8)el('path',{d:`M 0 ${i} L ${P.WIDTH} ${i}`,class:'road'});
const obstacles=[];for(const o of P.obstacles){const rect=el('rect',{x:o.x,y:o.y,width:o.w,height:o.h,rx:.12,class:'obstacle '+o.type});el('title',{},rect).textContent=o.type==='building'?`${o.id} / ${o.height} m`:o.id;el('text',{x:o.x+o.w/2,y:o.y+o.h/2,class:'obstacle-label'}).textContent=o.type==='building'?`${o.id} ${o.height}m`:o.id;obstacles.push({o,rect});}
let suppressClickUntil=0;for(let y=0;y<P.HEIGHT;y++)for(let x=0;x<P.WIDTH;x++){const c=el('rect',{x,y,width:1,height:1,class:'cell','data-x':x,'data-y':y,'aria-hidden':'true'});c.addEventListener('click',()=>{if(Date.now()>=suppressClickUntil)chooseCell(x,y)});}
const routeLayer=el('g',{'pointer-events':'none'}),startGroup=el('g',{'pointer-events':'none'}),endGroup=el('g',{'pointer-events':'none'}),droneLayer=el('g',{'pointer-events':'none'});
function marker(g,kind,text){el('circle',{r:.68,class:'marker '+kind},g);el('text',{x:0,y:.03,class:'marker-text'},g).textContent=text;g.setAttribute('visibility','hidden')}marker(startGroup,'start','S');marker(endGroup,'end','E');
function markers(){for(const [g,p] of [[startGroup,start],[endGroup,end]]){g.setAttribute('visibility',p?'visible':'hidden');if(p)g.setAttribute('transform',`translate(${p.x+.5} ${p.y+.5})`)}}
function setError(key){errorKey=key;const e=$('flight-error');e.hidden=!key;e.textContent=key?t('error_'+key):''}
function selectMode(m){mode=m;$('choose-start').classList.toggle('active',m==='start');$('choose-end').classList.toggle('active',m==='end')}
function chooseCell(x,y){if(P.groundBlocked(x,y)){setError('invalid');return}setError(null);if(mode==='start'){start={x,y};end=null;selectMode('end')}else{end={x,y};selectMode('start')}renderFields()}
function cell(p){if(!p)return '—';let n=p.y+1,s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s+(p.x+1)}
function renderFields(){$('start-label').textContent=cell(start);$('end-label').textContent=cell(end);markers();const h=Number(height.value);obstacles.forEach(({o,rect})=>{if(o.type==='building')rect.setAttribute('class','obstacle building '+(!height.value||!Number.isFinite(h)||h<=o.height+P.CLEARANCE?'blocked':'clear'))})}
function clock(n){n=Math.max(0,Math.floor(n));const day=Math.floor(n/86400);n%=86400;const s=[Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(v=>String(v).padStart(2,'0')).join(':');return day?`${s} (+${day} ${t('nextDay')})`:s}
function bounds(){return tasks.length?{start:Math.min(...tasks.map(x=>x.requested)),end:Math.max(...tasks.map(x=>x.departure+x.trajectory.duration))}:{start:0,end:0}}
function resetTimeline(){stop();simTime=bounds().start;$('flight-scrub').value='0';renderAnimation()}
function plan(){if(!start||!end||!/^\d{2}:\d{2}$/.test(time.value)){setError('missing');return}if(tasks.length>=12){setError('limit');return}const p={height:Number(height.value),speed:Number(speed.value),verticalSpeed:Number(vertical.value)};if(!height.value||!speed.value||!vertical.value||!Number.isFinite(p.height)||!Number.isFinite(p.speed)||!Number.isFinite(p.verticalSpeed)||p.height<1||p.height>500||p.speed<.1||p.speed>100||p.verticalSpeed<.1||p.verticalSpeed>30){setError('parameters');return}
 const result=P.findPath(start,end,p.height);if(result.error){setError(result.error==='invalid_endpoint'?'invalid':result.error==='same_point'?'same':'no_route');return}const trajectory=P.trajectory(result.path,p.height,p.speed,p.verticalSpeed),[hh,mm]=time.value.split(':').map(Number),requested=hh*3600+mm*60,s=P.schedule(trajectory,requested,tasks);if(s.error){setError('no_schedule');return}setError(null);const id=nextId++,color=colours.find(c=>!tasks.some(task=>task.color===c));tasks.push({id,start:{...start},end:{...end},model:model.value,params:p,requested,departure:s.departure,delay:s.delay,path:result.path,distance:result.distanceMeters,trajectory,color});selected=tasks.length-1;renderTasks();renderRoutes();resetTimeline()}
function renderRoutes(){routeLayer.replaceChildren();for(const [i,task] of tasks.entries())el('polyline',{class:'route-line multi-route',points:task.path.map(p=>`${p.x+.5},${p.y+.5}`).join(' '),style:`stroke:${task.color};opacity:${selected===i?1:.55};stroke-width:${selected===i?.36:.22}`},routeLayer)}
function removeTask(i){stop();tasks.splice(i,1);selected=tasks.length?Math.min(i,tasks.length-1):-1;setError(null);renderTasks();renderRoutes();resetTimeline()}
function renderTasks(){const list=$('queue-list');list.replaceChildren();$('clear-tasks').disabled=!tasks.length;$('flight-play').disabled=!tasks.length;$('flight-scrub').disabled=!tasks.length;if(!tasks.length){const p=document.createElement('p');p.className='flight-queue-empty';p.textContent=t('empty');list.append(p)}
 tasks.forEach((task,i)=>{const row=document.createElement('div');row.className='mission-row'+(selected===i?' selected':'');const btn=document.createElement('button');btn.type='button';btn.className='mission-select';const title=document.createElement('strong');const dot=document.createElement('i');dot.style.background=task.color;title.append(dot,document.createTextNode(`${t('task')} ${task.id} · ${t('aircraft')} ${task.model}`));const summary=document.createElement('small');summary.textContent=`${cell(task.start)} → ${cell(task.end)} · ${t('requested')} ${clock(task.requested)}`;const detail=document.createElement('small');detail.textContent=`${t('actual')} ${clock(task.departure)} · ${task.delay?`${t('delayed')} ${task.delay} ${t('seconds')}`:t('noDelay')}`;btn.append(title,summary,detail);btn.addEventListener('click',()=>{selected=i;renderTasks();renderRoutes();renderAnimation()});const del=document.createElement('button');del.type='button';del.className='mission-remove';del.textContent='×';del.setAttribute('aria-label',`${t('remove')} ${task.id}`);del.addEventListener('click',()=>removeTask(i));row.append(btn,del);list.append(row)});
 const result=$('flight-result');result.hidden=selected<0;if(selected>=0){const a=tasks[selected];result.textContent=`${t('distance')} ${(a.distance/1000).toFixed(2)} km · ${t('duration')} ${(a.trajectory.duration/60).toFixed(1)} ${t('min')} · ${t('arrival')} ${clock(a.departure+a.trajectory.duration)}`}}
function renderAnimation(){droneLayer.replaceChildren();const range=bounds();if(!tasks.length){$('flight-clock').textContent='—';$('flight-phase').textContent='';return}$('flight-clock').textContent=clock(simTime);let active=0,waiting=0,arrived=0;for(const task of tasks){let elapsed=simTime-task.departure;if(elapsed<0){waiting++;continue}if(elapsed>task.trajectory.duration){arrived++;continue}active++;let pos=P.positionAt(task.path,elapsed,task.params.height,task.params.speed,task.params.verticalSpeed);const group=el('g',{transform:`translate(${pos.point.x+.5} ${pos.point.y+.5})`},droneLayer);el('circle',{r:.72,fill:task.color,stroke:'#fff','stroke-width':.1},group);el('text',{x:0,y:.03,class:'marker-text'},group).textContent=String(task.id)}$('flight-phase').textContent=`${t('active')} ${active} · ${t('waiting')} ${waiting} · ${t('arrived')} ${arrived}`;if(range.end>range.start)$('flight-scrub').value=String(Math.round((simTime-range.start)/(range.end-range.start)*1000))}
function stop(){playing=false;lastFrame=null;if(frame)cancelAnimationFrame(frame);frame=null;$('flight-play').textContent=t('play')}
function tick(stamp){if(!playing||!tasks.length)return;if(lastFrame!==null)simTime+=Math.min((stamp-lastFrame)/1000,.2)*20;lastFrame=stamp;const range=bounds();if(simTime>=range.end){simTime=range.end;stop()}renderAnimation();if(playing)frame=requestAnimationFrame(tick)}
let zoom=1,viewX=0,viewY=0,drag=null;function applyView(){const w=P.WIDTH/zoom,h=P.HEIGHT/zoom;viewX=Math.max(0,Math.min(P.WIDTH-w,viewX));viewY=Math.max(0,Math.min(P.HEIGHT-h,viewY));svg.setAttribute('viewBox',`${viewX} ${viewY} ${w} ${h}`);$('zoom-level').textContent=Math.round(zoom*100)+'%';$('zoom-in').disabled=zoom>=4;$('zoom-out').disabled=zoom<=1}function zoomTo(next,anchor){const oldW=P.WIDTH/zoom,oldH=P.HEIGHT/zoom,a=anchor||{x:viewX+oldW/2,y:viewY+oldH/2},rx=(a.x-viewX)/oldW,ry=(a.y-viewY)/oldH;zoom=Math.max(1,Math.min(4,next));viewX=a.x-rx*P.WIDTH/zoom;viewY=a.y-ry*P.HEIGHT/zoom;applyView()}
$('zoom-in').addEventListener('click',()=>zoomTo(zoom*1.5));$('zoom-out').addEventListener('click',()=>zoomTo(zoom/1.5));$('zoom-reset').addEventListener('click',()=>{zoom=1;viewX=0;viewY=0;applyView()});svg.addEventListener('wheel',e=>{e.preventDefault();const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;zoomTo(zoom*(e.deltaY<0?1.25:.8),p.matrixTransform(svg.getScreenCTM().inverse()))},{passive:false});svg.addEventListener('pointerdown',e=>{if(e.button!==0||zoom<=1)return;drag={x:e.clientX,y:e.clientY,viewX,viewY,moved:false,id:e.pointerId}});svg.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)>4){drag.moved=true;svg.setPointerCapture(e.pointerId)}if(drag.moved){const r=svg.getBoundingClientRect();viewX=drag.viewX-dx*(P.WIDTH/zoom)/r.width;viewY=drag.viewY-dy*(P.HEIGHT/zoom)/r.height;applyView()}});function endDrag(e){if(!drag||drag.id!==e.pointerId)return;if(drag.moved)suppressClickUntil=Date.now()+300;drag=null}svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointercancel',endDrag);applyView();
$('choose-start').addEventListener('click',()=>selectMode('start'));$('choose-end').addEventListener('click',()=>selectMode('end'));model.addEventListener('change',()=>{const p=P.profiles[model.value];height.value=p.height;speed.value=p.speed;vertical.value=P.VERTICAL_SPEED;setError(null);renderFields()});[height,speed,vertical].forEach(input=>input.addEventListener('input',()=>{setError(null);renderFields()}));$('flight-plan').addEventListener('click',plan);$('clear-tasks').addEventListener('click',()=>{stop();tasks=[];selected=-1;nextId=1;setError(null);renderTasks();renderRoutes();resetTimeline()});$('flight-play').addEventListener('click',()=>{if(!tasks.length)return;if(playing){stop();return}if(simTime>=bounds().end)simTime=bounds().start;playing=true;lastFrame=null;$('flight-play').textContent=t('pause');frame=requestAnimationFrame(tick)});$('flight-scrub').addEventListener('input',e=>{if(!tasks.length)return;stop();const r=bounds();simTime=r.start+(r.end-r.start)*Number(e.target.value)/1000;renderAnimation()});
function translate(){lang=document.documentElement.lang.startsWith('en')?'en':'zh';intro.querySelector('h1').textContent=t('title');intro.querySelector('p').textContent=t('intro');intro.querySelector('.status').textContent=t('badge');host.querySelectorAll('[data-f]').forEach(e=>e.textContent=t(e.dataset.f));svg.setAttribute('aria-label',t('mapAria'));$('zoom-in').setAttribute('aria-label',t('zoomIn'));$('zoom-out').setAttribute('aria-label',t('zoomOut'));document.querySelector('.flight-zoom').setAttribute('aria-label',t('zoomGroup'));$('flight-scrub').setAttribute('aria-label',t('scrub'));foot.textContent=t('foot');renderFields();renderTasks();renderRoutes();renderAnimation();if(errorKey)setError(errorKey);$('flight-play').textContent=t(playing?'pause':'play')}
